from itertools import product
from sympy import Matrix, ZZ
from sympy.matrices.normalforms import smith_normal_form

LOW=(2,2,0,0,0)
UP=(5,5,5,5,5)

def deg(x): return sum(x)
def partstr(x):
    y=tuple(a for a in x if a)
    return ''.join(map(str,y)) if y else '0'
def contains(x,y): return all(a>=b for a,b in zip(x,y))
def horiz(lam,nu):
    # nu/lam is a horizontal strip iff nu_k >= lam_k >= nu_{k+1}.
    return contains(nu,lam) and all(lam[k] >= (nu[k+1] if k+1<len(nu) else 0) for k in range(len(lam)))

parts=[]
for x in product(range(6), repeat=5):
    if all(x[k]>=x[k+1] for k in range(4)) and contains(x,LOW):
        parts.append(x)
parts.sort(key=lambda z:(deg(z),z), reverse=False)
bydeg={e:[x for x in parts if deg(x)==e] for e in range(4,26)}
free_total=0
all_unit=True
print('parameters i=j=2, p=c=3, lower=22, upper=55555')
for e in range(4,26):
    cols=bydeg[e]
    rows=[]
    for t in range(1,6):
        for lam in bydeg.get(e-t,[]):
            row=[1 if horiz(lam,nu) and deg(nu)-deg(lam)==t else 0 for nu in cols]
            if any(row): rows.append(row)
    if rows:
        S=smith_normal_form(Matrix(rows), domain=ZZ)
        diag=[abs(int(S[k,k])) for k in range(min(S.rows,S.cols)) if S[k,k]!=0]
        rank=len(diag)
    else:
        diag=[]; rank=0
    unit=all(z==1 for z in diag)
    all_unit=all_unit and unit
    qrank=len(cols)-rank
    free_total += qrank
    print('e=%2d cols=%2d rows=%3d rank=%2d snf=%s qrank=%d' % (e,len(cols),len(rows),rank,diag,qrank))
print('TOTAL_Q_RANK=%d ALL_NONZERO_SNF_UNITS=%s' % (free_total,all_unit))
F1=['22','32','42','52','33','43','53','44','54','55']
F2=['22','221','222','2211','2221','2222','22111','22211','22221','22222']
actual={partstr(x) for x in parts}
print('F1_SIZE=%d F1_IN_INTERVAL=%s' % (len(F1),all(z in actual for z in F1)))
print('F2_SIZE=%d F2_IN_INTERVAL=%s' % (len(F2),all(z in actual for z in F2)))
print('RESULT: PASS')
